import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";
import { ALL_SHAPES, asCategory, isHello, isTick, parseMessage } from "../src/protocol";

// Conformance with the Go side: these files are generated by
// `go test ./internal/protocol -update` (docs/TESTING.md "Frontend tests").
const read = (name: string): string =>
  readFileSync(new URL(`../../testdata/protocol/${name}`, import.meta.url), "utf8");

type Json = Record<string, unknown>;
const keys = (o: unknown): string[] => Object.keys(o as Json).sort();
const shapeKeys = (s: object): string[] => Object.keys(s).sort();

function expectExactKeys(name: keyof typeof ALL_SHAPES, obj: unknown): void {
  expect(keys(obj), `${name} fields`).toEqual(shapeKeys(ALL_SHAPES[name]));
}

describe("protocol conformance with Go examples", () => {
  it("hello.json validates and has exactly the declared fields", () => {
    const raw = read("hello.json");
    const msg = parseMessage(raw);
    expect(msg && isHello(msg)).toBe(true);
    const hello = JSON.parse(raw) as Json & { server: Json; districts: Json[]; hosts: Json[] };
    expectExactKeys("hello", hello);
    expectExactKeys("server", hello.server);
    for (const d of hello.districts) expectExactKeys("district", d);
    for (const h of hello.hosts) {
      expectExactKeys("host", h);
      for (const s of h.services as Json[]) expectExactKeys("service", s);
      if (h.geo !== null) expectExactKeys("geo", h.geo);
    }
  });

  for (const file of ["tick.json", "events.json"]) {
    it(`${file} validates and has exactly the declared fields`, () => {
      const raw = read(file);
      const msg = parseMessage(raw);
      expect(msg && isTick(msg)).toBe(true);
      const tick = JSON.parse(raw) as Json & { stats: Json; flows: Json[]; hosts: Json[]; events: Json[] };
      expectExactKeys("tick", tick);
      expectExactKeys("stats", tick.stats);
      for (const f of tick.flows) expectExactKeys("flow", f);
      for (const h of tick.hosts) expectExactKeys("host", h);
      for (const e of tick.events) expectExactKeys("event", e);
    });
  }

  it("events.json covers every event kind", () => {
    const tick = JSON.parse(read("events.json")) as { events: { kind: string }[] };
    expect(tick.events.map((e) => e.kind).sort()).toEqual(["flood", "host_idle", "port_scan"]);
  });
});

describe("parseMessage", () => {
  it("rejects malformed and wrong-version messages", () => {
    expect(parseMessage("{bad")).toBeNull();
    const hello = JSON.parse(read("hello.json")) as Json;
    expect(parseMessage(JSON.stringify({ ...hello, v: 2 }))).toBeNull();
    const { hosts: _hosts, ...missing } = hello;
    expect(parseMessage(JSON.stringify(missing))).toBeNull();
  });

  it("ignores unknown fields", () => {
    const hello = JSON.parse(read("hello.json")) as Json;
    expect(parseMessage(JSON.stringify({ ...hello, future_field: 1 }))).not.toBeNull();
  });

  it("maps unknown categories to other", () => {
    expect(asCategory("https")).toBe("https");
    expect(asCategory("quantum")).toBe("other");
  });
});
